#!/usr/bin/env python3
"""Compile every Iteration-2 result into iter2/REPORT.md (numbers and neutral captions; the interpretation is written separately).

Reads the summary files the pipeline stages leave behind; a section whose inputs are missing says so instead of failing.
Usage: python make_report.py
"""
import csv
import json
import statistics
import subprocess
import sys
from pathlib import Path

R = Path("results")
out = ["# Iteration 2: multi-camera semantic exchange, compiled results\n",
       "Generated by `make_report.py` from the files under `results/`. Captions state what each table is; they carry no interpretation.\n"]


def section(title, fn):
    out.append(f"\n## {title}\n")
    try:
        fn()
    except Exception as e:                       # a missing stage must not hide the others
        out.append(f"_not available: {type(e).__name__}: {e}_\n")


def f2(v, nd=2):
    return "-" if v is None else f"{v:.{nd}f}"


def variants_table(path, keys):
    s = json.loads(Path(path).read_text())
    head = "| variant | " + " | ".join(k[1] for k in keys) + " |"
    out.append(head); out.append("|" + "---|" * (len(keys) + 1))
    for v, d in s["variants"].items():
        out.append(f"| {v} | " + " | ".join(str(int(d[k[0]])) if k[0] == "n_cases" else f2(d.get(k[0])) for k in keys) + " |")
    for k, v in s.get("paired_abs_error_vs_gt", {}).items():
        if v:
            out.append(f"\n- paired |error| vs ground truth, `{k}`: {v['mean_diff']:+.2f} (95% CI {v['ci95'][0]:+.2f} to {v['ci95'][1]:+.2f}), n={v['n']}")
    out.append("")


KEYS = [("n_cases", "cases"), ("mean_cars_4wheel", "mean cars"), ("gt_mean_cars_4wheel", "GT cars"), ("cars_4wheel_mae_vs_gt", "cars MAE"),
        ("cars_4wheel_bias_vs_gt", "cars bias"), ("cars_4wheel_within1_vs_gt", "within 1"), ("mean_pedestrians", "mean people"),
        ("vehicle_recall", "veh recall"), ("vehicle_precision", "veh prec"), ("person_recall", "person recall"), ("seconds", "s/img")]


def full_run():
    out.append("CARLA v2, 112 cases, 1024x576, Cityscapes palette. Recall/precision are against the detector's own output on the original photo.\n")
    variants_table(R / "carla_v2/analysis/summary.json", KEYS)


def pilot():
    out.append("CARLA v2, cases 1-24: single view (k1), fused prompt, shuffled-caption control, IP-Adapter variants.\n")
    variants_table(R / "pilot_cs/analysis/summary.json", KEYS)


def run_text(script, title):
    p = subprocess.run([sys.executable, script], capture_output=True, text=True)
    out.append(title + "\n"); out.append("```"); out.append((p.stdout + p.stderr).strip()); out.append("```\n")


def tuning():
    run_text("compare_tune.py", "Generation settings, prompt_only, cases 1-24 (paired against the default).")


def hr():
    run_text("compare_hr.py", "prompt_only at 1280x704 vs 1024x576, all cases.")


def geofuse():
    out.append("Blob counting on the received segmentation maps and ground-plane fusion across cameras (CARLA v2, vs Rec1-visible ground truth).\n")
    out.append("| min blob area | gate m | group | rule | MAE | bias | within 1 |"); out.append("|---|---|---|---|---|---|---|")
    for d in sorted(R.glob("geofuse_a*_g*")):
        if not (d / "summary.json").exists():
            continue
        s = json.loads((d / "summary.json").read_text())
        for g, rules in s["counts_vs_gt"].items():
            for rule, v in rules.items():
                if g == "vehicle" or rule in ("F0", "F4", "F5"):
                    out.append(f"| {s['min_area']} | {s['gate']} | {g} | {rule} | {f2(v['mae'])} | {f2(v['bias'])} | {f2(v['within1'])} |")
    out.append("\nF0 = Rec1's own blobs; F2 = + every object projecting into Rec1's frame; F3 = + objects >= 2 cameras agree on; "
               "F4 = + objects landing on Rec1's own vehicle pixels; F5 = F4 with the >= 2 cameras condition.\n")


def v3():
    out.append("CARLA v3 (instance ids and world positions saved), full pipeline.\n")
    variants_table(R / "v3/analysis/summary.json", KEYS)
    txt = Path("jobs/v3_eval.txt")
    if txt.exists():
        out.append("Scene-level evaluation (reference Rec1 = visible from cam1; union = visible from any camera; positions in metres):\n")
        out.append("```"); out.append(txt.read_text(errors="replace").strip()); out.append("```\n")


def realworld():
    out.append("Real-world Astana phone triplets (every 6th core case). No ground truth: mean detections per photo only.\n")
    rows = list(csv.DictReader(open(R / "rw_core/analysis/counts.csv")))
    out.append("| variant | cases | cars+trucks+buses | people | two-wheelers+motorcycles |"); out.append("|---|---|---|---|---|")
    for v in ("oracle_gen", "k1", "prompt_only"):
        rs = [r for r in rows if r["variant"] == v]
        if rs:
            out.append(f"| {v} | {len(rs)} | {statistics.fmean(int(r['cars_4wheel']) for r in rs):.2f} | {statistics.fmean(int(r['person']) for r in rs):.2f} | "
                       f"{statistics.fmean(int(r['motorcycle']) + int(r['bicycle']) for r in rs):.2f} |")
    out.append("")


section("1. Full run, CARLA v2 (112 cases)", full_run)
section("2. Pilot ablations (24 cases)", pilot)
section("3. Generation settings", tuning)
section("4. Resolution 1280x704 on all cases", hr)
section("5. Blob counting and ground-plane fusion", geofuse)
section("6. CARLA v3 with scene-level ground truth", v3)
section("7. Real-world sample", realworld)
Path("REPORT.md").write_text("\n".join(out), encoding="utf-8")
print("wrote REPORT.md,", len(out), "lines")
